-- Speakwise isolated database migration. Apply only to a NEW Speakwise Supabase project.
begin;
create table public.speakwise_topics(
 id text primary key,section text not null check(section in ('life','ielts')),
 name text not null,vi text not null,icon text not null default 'book',
 description text not null default ''
);
create table public.speakwise_entries(
 id text primary key,
 owner_id uuid references auth.users(id) on delete cascade,
 topic_id text not null references public.speakwise_topics(id),
 phrase text not null,ipa text not null default '',meaning text not null,
 example text not null,note text not null default '',
 source text not null default '',added_at date not null default current_date,
 updated_at timestamptz not null default now()
);
create index speakwise_entries_owner_idx on public.speakwise_entries(owner_id);
create index speakwise_entries_topic_idx on public.speakwise_entries(topic_id);
create table public.speakwise_progress(
 user_id uuid not null references auth.users(id) on delete cascade,
 entry_id text not null references public.speakwise_entries(id) on delete cascade,
 level int not null default 0 check(level between 0 and 5),
 reviews int not null default 0,next_review date,starred boolean not null default false,
 updated_at timestamptz not null default now(),primary key(user_id,entry_id)
);
create table public.speakwise_hidden(
 user_id uuid not null references auth.users(id) on delete cascade,
 entry_id text not null references public.speakwise_entries(id) on delete cascade,
 primary key(user_id,entry_id)
);
create table public.speakwise_sessions(
 id text primary key,
 owner_id uuid not null references auth.users(id) on delete cascade,
 topic text not null default '',question text not null,answer text not null,
 collocations jsonb not null default '[]'::jsonb,
 practiced_at date not null default current_date,
 updated_at timestamptz not null default now()
);
create index speakwise_sessions_owner_idx on public.speakwise_sessions(owner_id);
alter table public.speakwise_topics enable row level security;
alter table public.speakwise_entries enable row level security;
alter table public.speakwise_progress enable row level security;
alter table public.speakwise_hidden enable row level security;
alter table public.speakwise_sessions enable row level security;
create policy sw_topics_read on public.speakwise_topics for select to anon,authenticated using(true);
create policy sw_entries_read on public.speakwise_entries for select to anon,authenticated using(owner_id is null or owner_id=(select auth.uid()));
create policy sw_entries_insert on public.speakwise_entries for insert to authenticated with check(owner_id=(select auth.uid()));
create policy sw_entries_update on public.speakwise_entries for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy sw_entries_delete on public.speakwise_entries for delete to authenticated using(owner_id=(select auth.uid()));
create policy sw_progress_read on public.speakwise_progress for select to authenticated using(user_id=(select auth.uid()));
create policy sw_progress_insert on public.speakwise_progress for insert to authenticated with check(user_id=(select auth.uid()));
create policy sw_progress_update on public.speakwise_progress for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy sw_hidden_read on public.speakwise_hidden for select to authenticated using(user_id=(select auth.uid()));
create policy sw_hidden_insert on public.speakwise_hidden for insert to authenticated with check(user_id=(select auth.uid()));
create policy sw_hidden_delete on public.speakwise_hidden for delete to authenticated using(user_id=(select auth.uid()));
create policy sw_sessions_read on public.speakwise_sessions for select to authenticated using(owner_id=(select auth.uid()));
create policy sw_sessions_insert on public.speakwise_sessions for insert to authenticated with check(owner_id=(select auth.uid()));
create policy sw_sessions_update on public.speakwise_sessions for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy sw_sessions_delete on public.speakwise_sessions for delete to authenticated using(owner_id=(select auth.uid()));
create function public.speakwise_touch() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end;$$;
create trigger sw_entries_touch before update on public.speakwise_entries for each row execute function public.speakwise_touch();
create trigger sw_progress_touch before update on public.speakwise_progress for each row execute function public.speakwise_touch();
create trigger sw_sessions_touch before update on public.speakwise_sessions for each row execute function public.speakwise_touch();
grant select on public.speakwise_topics,public.speakwise_entries to anon,authenticated;
grant insert,update,delete on public.speakwise_entries to authenticated;
grant select,insert,update,delete on public.speakwise_progress,public.speakwise_hidden,public.speakwise_sessions to authenticated;
commit;
